 static bool Finish(Task t){DateTime until=DateTime.UtcNow.AddSeconds(8);while(!t.IsCompleted&&DateTime.UtcNow<until)Pump(5);if(t.IsFaulted)Console.WriteLine(t.Exception);return t.Status==TaskStatus.RanToCompletion;}
